final_submission.code:
std::vector<std::pair<Point3d, Point3d>> rays;
for (int i = 0; i < numberOfChecks; i++) {
    double x = std::rand() / (double)RAND_MAX;
    double y = std::rand() / (double)RAND_MAX;
    double z = std::rand() / (double)RAND_MAX;
    Point3d direction(x, y, z);
    direction = direction / std::sqrt(direction.squared_length());
    Point3d end = p + direction * 1000.0;
    rays.push_back(std::make_pair(p, end));
}

int intersections = 0;
for (const auto& ray : rays) {
    std::vector<std::pair<Point3d, Point3d>> intersections_with_ray;
    tree.all_intersections(ray.first, ray.second, std::back_inserter(intersections_with_ray));
    if (intersections_with_ray.size() % 2 != 0) {
        intersections++;
    }
}

return intersections == numberOfChecks;

